/**
 * WorkplaceEvaluationFile.jsx — Page that shows one workplace evaluation as a PDF (manager, employer or student).
 *
 * Location: components/evaluations/WorkplaceEvaluationFile.jsx
 * Routes: /manager/evaluations/:id, /employer/evaluations/:id and /student/evaluations/:id
 *         (opened by the "Download the evaluation" button of WorkplaceEvaluationCard)
 *
 * The PDF is generated by the backend on demand, so it always reflects the current state/signatures.
 * - FR / EN switch: changes the language of the PDF shown (independent of the language of the
 *   interface; it starts in the interface language).
 * - "Download this PDF": saves the language currently shown.
 * - "Download both": saves the French and the English PDFs one after the other.
 *
 * Opening this page closes the notification of this workplace evaluation
 * (and only this one: session-scoped, see NotificationsProvider).
 *
 * Downloaded file name: {language}-{docType}-{studentName}.{extension}
 *   e.g. fr-workplace-evaluation-Alex_Tremblay.pdf
 * The student name comes from the link state set by WorkplaceEvaluationCard ({studentName}).
 * When the page is opened directly (no link state) the student name is skipped.
 *
 * Access control is handled by <RequireRole/> in App.jsx, and enforced again by the backend
 * (an evaluation of another party is not found).
 */

import {useCallback, useMemo, useState} from 'react';
import {Link, useLocation, useOutletContext, useParams} from 'react-router-dom';
import {useTranslation} from 'react-i18next';
import Button from '../../styles/Button.jsx';
import {getAuthClasses, getPostInternshipClasses} from '../../styles/AppStyles.jsx';
import {getWorkplaceEvaluationFile} from '../api/Api.jsx';
import {TARGET_TYPE, useCloseShownNotifications} from '../notification/NotificationsProvider.jsx';
import {blobUrlFromFile, buildFileName, saveFile} from '../../utils/Documents.js';
import PdfPreview from '../documents/PdfPreview.jsx';
import {getEvaluationRole} from "../../utils/WorkplaceEvaluation.js";

const LANGUAGES = ["FR", "EN"];
const DOC_TYPE = "workplace-evaluation";

const WorkplaceEvaluationFile = () => {
    const {t, i18n} = useTranslation();
    const {dark, user} = useOutletContext();
    const {id} = useParams();
    const {state} = useLocation();
    const {pageClass} = getAuthClasses(dark);
    const s = getPostInternshipClasses(dark);
    const {basePath} = getEvaluationRole(user);

    const [language, setLanguage] = useState(i18n.resolvedLanguage?.startsWith("fr") ? "FR" : "EN");
    const [downloading, setDownloading] = useState(null); // "FR" | "EN" | "BOTH" | null
    const [downloadFailed, setDownloadFailed] = useState(false);

    const evaluationId = Number(id);
    const studentName = state?.studentName;

    // Opening the evaluation closes its notification (must be memoized)
    const shownIds = useMemo(() => [evaluationId], [evaluationId]);
    useCloseShownNotifications(TARGET_TYPE.WORKPLACE_EVALUATION, shownIds);

    // Stable reference per language: PdfPreview reloads the PDF when it changes
    const getEvaluationUrl = useCallback(
        async (evaluationId) => blobUrlFromFile(await getWorkplaceEvaluationFile(evaluationId, language)),
        [language],
    );

    const download = async (languages, mode) => {
        setDownloading(mode);
        setDownloadFailed(false);
        try {
            for (const lang of languages) {
                const file = await getWorkplaceEvaluationFile(evaluationId, lang);
                saveFile(file, buildFileName({
                    language: lang,
                    docType: DOC_TYPE,
                    studentName,
                    originalName: file.fileName,
                }));
            }
        } catch {
            setDownloadFailed(true);
        } finally {
            setDownloading(null);
        }
    };

    const busy = downloading !== null;
    const segment = (active) => `px-4 py-1.5 text-sm font-semibold transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500 ${
        active
            ? "bg-indigo-600 text-white"
            : dark ? "bg-slate-800 text-slate-300 hover:bg-slate-700" : "bg-white text-gray-700 hover:bg-gray-100"
    }`;

    return (
        <div className={`${pageClass} items-start`}>
            <div className="w-full max-w-4xl min-w-0 space-y-4">
                <div className={s.headerSection}>
                    <div>
                        <h1 className={s.title}>{t("workplaceEvaluation.title")}</h1>
                        <p className={s.subtitle}>{t("workplaceEvaluation.file.subtitle")}</p>
                    </div>
                    <Button as={Link} to={basePath} tone="neutral" dark={dark} icon="arrow_back">
                        {t("workplaceEvaluation.file.back")}
                    </Button>
                </div>

                <div className="flex flex-wrap items-center justify-between gap-3">
                    <div role="group" aria-label={t("managerContracts.file.languageGroup")}
                         className={`inline-flex overflow-hidden rounded-lg border ${dark ? "border-slate-600" : "border-gray-300"}`}>
                        {LANGUAGES.map((lang) => (
                            <button
                                key={lang}
                                type="button"
                                aria-pressed={language === lang}
                                onClick={() => setLanguage(lang)}
                                className={segment(language === lang)}
                            >
                                {t(`managerContracts.file.language.${lang.toLowerCase()}`)}
                            </button>
                        ))}
                    </div>

                    <div role="group" aria-label={t("managerContracts.download.group")}
                         className="flex flex-wrap items-center justify-end gap-2">
                        <Button tone="accent" lockTone dark={dark} icon="download" disabled={busy}
                                onClick={() => download([language], language)}>
                            {downloading === language
                                ? t("managerContracts.file.downloading")
                                : t("managerContracts.file.downloadCurrent", {
                                    language: t(`managerContracts.file.language.${language.toLowerCase()}`),
                                })}
                        </Button>
                        <Button tone="accent" lockTone dark={dark} icon="download" disabled={busy}
                                onClick={() => download(LANGUAGES, "BOTH")}>
                            {downloading === "BOTH"
                                ? t("managerContracts.file.downloading")
                                : t("managerContracts.file.downloadBoth")}
                        </Button>
                    </div>
                </div>

                {downloadFailed && (
                    <p className={`text-sm ${dark ? "text-red-300" : "text-red-600"}`} role="alert">
                        {t("managerContracts.download.failed")}
                    </p>
                )}

                <PdfPreview
                    doc={{id: evaluationId, fileName: t("workplaceEvaluation.title")}}
                    dark={dark}
                    getUrl={getEvaluationUrl}
                />
            </div>
        </div>
    );
};

export default WorkplaceEvaluationFile;